using UnityEngine;
namespace Vanta.Vehicles{[RequireComponent(typeof(Rigidbody))]public sealed class VehicleController:MonoBehaviour{[SerializeField]float acceleration=12f,turnRate=70f,maxSpeed=28f,health=100f;Rigidbody body;public float Health=>health;void Awake(){body=GetComponent<Rigidbody>();}void FixedUpdate(){float throttle=Input.GetAxis("Vertical"),steer=Input.GetAxis("Horizontal");body.AddForce(transform.forward*throttle*acceleration,ForceMode.Acceleration);body.MoveRotation(body.rotation*Quaternion.Euler(0,steer*turnRate*Time.fixedDeltaTime*Mathf.Clamp01(body.velocity.magnitude/5f),0));if(body.velocity.magnitude>maxSpeed)body.velocity=body.velocity.normalized*maxSpeed;}public void ApplyDamage(float amount){health=Mathf.Max(0,health-Mathf.Max(0,amount));}}}